// Two entry points share one pipeline: the CRM webhook, and internal calls (cascade touches, retries).
const src = $input.first().json;
const input = src.body ?? src;
if (!input.campaign_key) throw new Error('campaign_key is required');
if (!Array.isArray(input.recipients)) throw new Error('recipients must be an array');
return [{ json: {
  campaign_key: String(input.campaign_key),
  run_name: input.run_name ?? null,
  touch_label: input.touch_label ?? null,
  attempt: Number(input.attempt ?? 1),
  skip_ab: input.skip_ab === true,
  recipients: input.recipients,
} }];

// Resolve the campaign, name the run, clean the recipient list.
const cfg = $('Load config').first().json;
const req = $('Normalize trigger').first().json;
const campaign = cfg.campaigns[req.campaign_key];
if (!campaign) throw new Error(`Unknown campaign "${req.campaign_key}" — add it to 00-config`);

// Voice APIs want E.164. CRMs rarely store it that way.
function toE164(raw, cc) {
  if (!raw) return null;
  let s = String(raw).replace(/[^\d+]/g, '');
  if (s.startsWith('00')) s = '+' + s.slice(2);
  if (!s.startsWith('+') && cc && s.startsWith('0')) s = '+' + cc + s.slice(1);
  return /^\+\d{8,15}$/.test(s) ? s : null;
}

const today = DateTime.now().setZone(campaign.timezone).toISODate();
let run_name = req.run_name || `${campaign.label} ${today}`;
if (req.touch_label) run_name += ` (${req.touch_label})`;

const seen = new Set(); const rejected = [];
const recipients = [];
for (const r of req.recipients) {
  const id = r.id != null ? String(r.id) : '';
  const phone = toE164(r.phone_number ?? r.phone, campaign.default_country_code);
  if (!id || !phone) { rejected.push({ id, reason: !id ? 'missing id' : 'invalid phone' }); continue; }
  if (seen.has(id)) continue;
  seen.add(id);
  recipients.push({ ...r, id, phone_number: phone });
}

return [{ json: { campaign_key: req.campaign_key, campaign, run_name, attempt: req.attempt,
                  skip_ab: req.skip_ab, recipients, rejected } }];

// Deterministic A/B: same person + same salt → same arm, on every run and every server.
// FNV-1a over "salt:id", bucket 0-99. A per-campaign salt keeps experiments independent.
const run = $('Resolve run').first().json;
const ab = run.campaign.ab_test;
function fnv1a(str) {
  let h = 0x811c9dc5;
  for (let i = 0; i < str.length; i++) { h ^= str.charCodeAt(i); h = Math.imul(h, 0x01000193) >>> 0; }
  return h;
}
return $input.all().map(({ json }) => {
  let ab_arm = 'treatment';
  if (ab?.enabled && !run.skip_ab) {
    const bucket = fnv1a(`${ab.salt || run.campaign_key}:${json.id}`) % 100;
    ab_arm = bucket < (ab.treatment_pct ?? 50) ? 'treatment' : 'control';
  }
  return { json: { ...json, ab_arm } };
});

// Persist the arm on the CRM record so the control group is measurable later.
const run = $('Resolve run').first().json;
const ab = run.campaign.ab_test;
if (!ab?.enabled || run.skip_ab || !ab.crm_field) return [];
return $input.all().map(({ json }) => {
  const label = ab.labels[json.ab_arm];
  // NB: on multi-select fields most CRMs REPLACE the array — merge first if the field holds other values.
  return { json: { op: 'update_record', payload: { id: json.id, fields: { [ab.crm_field]: ab.multi_select ? [label] : label } } } };
});

// If the campaign has eligibility rules, fetch the live record for each person (state drifts between trigger and dial).
const rules = $('Resolve run').first().json.campaign.eligibility;
const fields = rules ? [...new Set([
  rules.status_field,
  ...rules.checklist.flatMap(c => [...(c.any_of ?? [c.field]), ...(c.exempt_if ?? []).map(e => e.field), ...(c.label_by ? [c.label_by.field] : [])]),
])] : [];
return $input.all().map(({ json }) => ({ json: rules
  ? { op: 'get_record', payload: { id: json.id, fields } }
  : { op: 'noop', payload: { id: json.id } } }));

// Pair lookups with people BY INDEX, explicitly — never via .first() inside a per-person loop.
const rules = $('Resolve run').first().json.campaign.eligibility;
const people = $('Treatment arm only').all();
const lookups = $input.all();
if (people.length !== lookups.length)
  throw new Error(`Adapter returned ${lookups.length} results for ${people.length} people — refusing to guess pairing`);

function evaluate(f) {
  const status = f[rules.status_field];
  if (!rules.allowed_statuses.includes(status)) return { eligible: false, ineligible_reason: `status is now "${status}"`, action_items: [] };
  const open = [];
  let started = 0;
  for (const item of rules.checklist) {
    const keys = item.any_of ?? [item.field];
    started += keys.filter(k => f[k] !== null && f[k] !== undefined && f[k] !== '').length;
    if ((item.exempt_if ?? []).some(e => e.values.includes(f[e.field]))) continue;
    const accepted = item.accepted_values ?? rules.accepted_values ?? ['Accepted'];
    if (keys.some(k => accepted.includes(f[k]))) continue;
    let label = item.label;
    if (item.label_by) label = item.label_by.map?.[f[item.label_by.field]] ?? item.label_by.default ?? label;
    open.push(label);
  }
  const eligible = open.length >= (rules.min_open_items ?? 1) && started >= (rules.min_started_items ?? 0);
  return { eligible, ineligible_reason: eligible ? null : `open items ${open.length}, started ${started}`, action_items: open };
}

return people.map(({ json: person }, i) => {
  const rec = lookups[i].json;
  if (!rules) return { json: { ...person, eligible: true, action_items: person.action_items ?? [] } };
  if (!rec.ok) return { json: { ...person, eligible: false, ineligible_reason: `lookup failed: ${rec.error}` } };
  return { json: { ...person, ...evaluate(rec.fields) } };
});

const recipients = $input.all().map(i => i.json);
if (!recipients.length) return [];          // nobody left to call → stop quietly
const c = $('Resolve run').first().json.campaign;
return [{ json: {
  recipients,
  calendar: c.booking?.enabled
    ? { op: 'availability', event_type_uri: c.booking.event_type_uri, lookahead_days: c.booking.lookahead_days ?? 7 }
    : { op: 'noop' },
} }];

// Build the voice-provider batch. campaign_key + run_name travel as dynamic variables,
// so every post-call webhook is self-describing (no extra API lookup to route it).
const cfg = $('Load config').first().json;
const run = $('Resolve run').first().json;
const c = run.campaign;
const cal = $input.first().json;
const { recipients } = $('Collect batch').first().json;

if (c.booking?.enabled && !cal.ok)
  throw new Error(`${run.run_name}: no calendar availability — not calling people with nothing to offer`);

const tz = c.timezone, loc = c.locale || 'en-GB';
const now = DateTime.now().setZone(tz).setLocale(loc);
const human = iso => DateTime.fromISO(iso).setZone(tz).setLocale(loc).toFormat(c.slot_format || "cccc d LLLL 'at' HH:mm");

const shared = {
  campaign_key: run.campaign_key,
  run_name: run.run_name,
  today: now.toFormat('cccc d LLLL yyyy'),
  tomorrow: now.plus({ days: 1 }).toFormat('cccc d LLLL yyyy'),
  next_availabilities: (cal.slots || []).slice(0, c.booking?.max_slots_offered ?? 12).map(human).join(', '),
};

const body = {
  call_name: run.run_name,
  agent_id: c.agent_id,
  agent_phone_number_id: c.phone_number_id || cfg.voice.phone_number_id,
  recipients: recipients.map(r => ({
    phone_number: r.phone_number,
    conversation_initiation_client_data: { dynamic_variables: {
      ...shared,
      contact_id: r.id,
      contact_name: r.name ?? '',
      contact_email: r.email ?? '',
      contact_phone: r.phone_number,
      action_item_count: (r.action_items ?? []).length,
      action_items_list: (r.action_items ?? []).map((a, i) => `${i + 1}. ${a}`).join('\n'),
      ...(r.variables ?? {}),
    } },
  })),
};
return [{ json: { body, recipient_count: recipients.length } }];

const run = $('Resolve run').first().json;
return [{ json: {
  campaign_key: run.campaign_key,
  run_name: run.run_name,
  attempt: run.attempt,
  batch_id: $input.first().json.id,
  recipients: $('Collect batch').first().json.recipients,
} }];
